def check_type_dict(value):
    """Verify that value is a dict or convert it to a dict and return it.

    Raises :class:`TypeError` if unable to convert to a dict

    :arg value: Dict or string to convert to a dict. Accepts ``k1=v2, k2=v2``.

    :returns: value converted to a dictionary
    """
    if isinstance(value, dict):
        return value

    if isinstance(value, string_types):
        parsed = True
        try:
            result = json.loads(value)
        except (ValueError, TypeError):
            try:
                result = literal_eval(value)
            except (ValueError, SyntaxError, TypeError, MemoryError, RecursionError):
                parsed = False
        if parsed and isinstance(result, dict):
            return result
        if parsed:
            raise TypeError('dictionary requested, string contains %s' % type(result).__name__)

        if '=' not in value or value.lstrip().startswith(('{', '[', '(')):
            raise TypeError('dictionary requested, could not parse JSON, a dictionary literal, or key=value pairs')

        fields = []
        field_buffer = []
        in_quote = None
        in_escape = False
        after_comma = False
        for c in value.strip():
            if in_escape:
                field_buffer.append(c)
                in_escape = False
            elif c == '\\':
                in_escape = True
            elif in_quote:
                if c == in_quote:
                    in_quote = None
                else:
                    field_buffer.append(c)
            elif c in ('\'', '"'):
                in_quote = c
            elif c == ',':
                field = ''.join(field_buffer)
                if not field and (not fields or after_comma):
                    raise TypeError('dictionary requested, empty key=value pair')
                if field:
                    fields.append(field)
                field_buffer = []
                after_comma = True
            elif c.isspace():
                field = ''.join(field_buffer)
                if field:
                    fields.append(field)
                    field_buffer = []
            else:
                field_buffer.append(c)
                after_comma = False

        if in_quote or in_escape:
            raise TypeError('dictionary requested, unterminated quote or escape in key=value pairs')
        field = ''.join(field_buffer)
        if field:
            fields.append(field)
        elif after_comma:
            raise TypeError('dictionary requested, empty key=value pair')

        result = {}
        for field in fields:
            key, separator, item = field.partition('=')
            if not separator or not key or not item:
                raise TypeError('dictionary requested, invalid key=value pair: %r' % field)
            result[key] = item
        return result

    raise TypeError('%s cannot be converted to a dict' % type(value))


def check_type_bool(value):
    """Verify that the value is a bool or convert it to a bool and return it.

    Raises :class:`TypeError` if unable to convert to a bool

    :arg value: String, int, or float to convert to bool. Valid booleans include:
         '1', 'on', 1, '0', 0, 'n', 'f', 'false', 'true', 'y', 't', 'yes', 'no', 'off'

    :returns: Boolean True or False
    """
    if isinstance(value, bool):
        return value

    if isinstance(value, string_types) or isinstance(value, (int, float)):
        return boolean(value)

    raise TypeError('%s cannot be converted to a bool' % type(value))
